// EDIT THIS LIST: one entry per class section. Paste each Google Sheet ID.
// 'section' must match the label used in the Streamlit app's secrets.toml.
const sections = [
  { section: 'Grade 1 - Sec A', sheetId: 'PASTE_SHEET_ID' },
  { section: 'Grade 1 - Sec B', sheetId: 'PASTE_SHEET_ID' },
  { section: 'Grade 2 - Sec A', sheetId: 'PASTE_SHEET_ID' },
  { section: 'Grade 2 - Sec B', sheetId: 'PASTE_SHEET_ID' },
];
return sections.map(s => ({ json: s }));

// Build the weekly HTML digest, grouped by Grade & Section.
const tz = 'Asia/Karachi';
// Trigger runs just after midnight on Sunday; step back so we still land in Saturday's ISO week.
const ref = $now.setZone(tz).minus({ minutes: 30 });
const week = ref.toFormat("kkkk-'W'WW");          // matches the app's label, e.g. 2026-W41
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/\n/g,'<br>');

const sections = $('Define Sections').all().map(i => i.json.section);
const grouped = {};
for (const it of $input.all()) {
  const row = it.json;
  if (!row['Timestamp'] || row['Week Number'] !== week) continue;   // current-week filter
  const p = it.pairedItem;
  const idx = typeof p === 'number' ? p : Array.isArray(p) ? p[0].item : p?.item;
  const label = sections[idx] ?? 'Unknown section';
  (grouped[label] = grouped[label] || []).push(row);
}

let html = `<div style="font-family:Arial,sans-serif;max-width:800px">
<h2>Weekly Class Log Report - ${week}</h2>
<p>Generated ${ref.toFormat('cccc, dd LLL yyyy')} (Asia/Karachi)</p>`;

for (const label of Object.keys(grouped).sort()) {
  const rows = grouped[label].sort((a,b) => String(a['Timestamp']).localeCompare(String(b['Timestamp'])));
  html += `<h3 style="background:#f0f4f8;padding:6px 10px;margin-top:24px">${esc(label)}</h3>
<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse;width:100%;font-size:14px">
<tr style="background:#fafafa"><th align="left">Teacher</th><th align="left">Subject</th><th align="left">Topics / Lessons Taught</th></tr>`;
  for (const r of rows) {
    html += `<tr><td valign="top">${esc(r['Teacher Name'])}</td><td valign="top">${esc(r['Subject'])}</td><td>${esc(r['Topics / Lessons Taught'])}</td></tr>`;
  }
  html += '</table>';
}

const missing = sections.filter(s => !grouped[s]);
if (missing.length) {
  html += `<h3 style="color:#b00020;margin-top:24px">No submissions this week</h3><ul>${missing.map(m => `<li>${esc(m)}</li>`).join('')}</ul>`;
}
html += '</div>';

return [{ json: { subject: `Weekly Class Log Report - ${week}`, html } }];
